import json
import numpy as np
from sympy import symbols, SOPform, And, Or, Not, true, false

spec = TASK["public"].get("specification")
rows = [tuple(map(int, x)) for x in spec["inputs"]]
labels = list(map(int, spec["outputs"]))
truth = dict(zip(rows, labels))
support = []
for j in range(10):
    if any(truth[x] != truth[x[:j] + (1-x[j],) + x[j+1:]] for x in rows):
        support.append(j)

variables = symbols("x0:10")
used = [variables[j] for j in support]
reduced = {tuple(x[j] for j in support): y for x, y in truth.items()}

def minimize(label):
    expression = SOPform(used, [list(x) for x, y in reduced.items() if y == label])
    if expression == false:
        return []
    if expression == true:
        return [()]
    products = expression.args if expression.func == Or else (expression,)
    return [
        product.args if product.func == And else (product,)
        for product in products
    ]

positive_class = 1
terms = minimize(positive_class)
if len(terms) > 34:
    positive_class = 0
    terms = minimize(positive_class)
assert len(terms) <= 34, "Minimized cover exceeds the available width."

names = ["w0", "b0", "w1", "b1", "w2", "b2", "w3", "b3", "out", "bias"]
