    positives = 0
    for literal in literals:
        negative = literal.func == Not
        variable = literal.args[0] if negative else literal
        arrays["w0"][channel, variable_index[variable]] = -1 if negative else 1
        positives += not negative
    arrays["b0"][channel] = 1 - positives

# Analytic identity transport; no network is evaluated.
